"""Meridian CRM §5 permission check migrated to Python."""

from __future__ import annotations


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether *user* may perform *action* on *record*."""

    role_id = user.get("ROLE_ID", "")

    # Permission rows are evaluated in supplied order; the first exact match
    # is the applicable legacy matrix row.
    matching_scope = None
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            matching_scope = row.get("scope", "")
            break

    # Missing permission rows deny by default.
    if matching_scope is None:
        return False

    # DELETE is permitted only for currently non-deleted records. Blank
    # boolean values have the legacy meaning N.
    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    # ADMIN bypasses row scope, but does not bypass the requirement that the
    # matching permission row exists.
    if role_id == "ADMIN":
        return True

    if matching_scope == "NONE":
        return False
    if matching_scope == "ALL":
        return True
    if matching_scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if matching_scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")

    # Unknown scopes are not permissions.
    return False
